from pathlib import Path
from html import escape
import json
p=Path(__file__).resolve().parent
capture=json.loads((p/'capture.json').read_text())
def chapters(name):
 return ''.join(f'<button data-video="{name}" data-time="{c["seconds"]}">{int(c["seconds"])//60}:{int(c["seconds"])%60:02d} · {escape(c["chapter"])}</button>' for c in capture['timeline'] if c['video']==name and c['chapter']!='Koniec')
screens=[('desktop-hero.png','Hero — wejście do instalacji'),('desktop-core-proximity.png','Core — oddech, żar i reakcja na kursor'),('desktop-selectors.png','Selektory — szkło w metalowych gniazdach'),('desktop-showroom.png','Showroom — sześć różnych szlifów'),('desktop-services-process-handoff.png','Usługi → Process — czyste przejście'),('desktop-process.png','Process — etapy połączone szyną'),('desktop-ecosystem.png','Ecosystem — przewody i głębia'),('desktop-contact.png','Kontakt — konsola optyczna'),('desktop-brief-focus.png','Brief — pola i focus'),('mobile-hero.png','Mobile — wejście'),('mobile-selectors.png','Mobile — selektory'),('mobile-showroom.png','Mobile — kryształ projektu')]
figures=''.join(f'<figure class="{"phone" if f.startswith("mobile") else ""}"><a href="{f}"><img src="{f}" loading="lazy" alt="{escape(label)}"></a><figcaption>{escape(label)}</figcaption></figure>' for f,label in screens)
html='''<!doctype html><html lang="pl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ProgressKit — living world · lokalny proof</title><style>
*{box-sizing:border-box}body{margin:0;background:#0b0a0e;color:#e9e4ea;font:16px/1.6 system-ui,sans-serif}main{max-width:1480px;margin:auto;padding:32px clamp(16px,4vw,60px) 80px}h1{font-size:clamp(30px,4.5vw,60px);line-height:1.08;letter-spacing:-.045em;max-width:20ch}h2{font-size:28px;margin-top:56px}p{max-width:85ch;color:#c3bac5}a{color:#f1b7ca}nav,.chapters{display:flex;gap:10px;flex-wrap:wrap}nav a,button{background:linear-gradient(#39323d,#17121c);color:#eee8f1;border:1px solid #776477;border-radius:8px;padding:12px 16px;font:600 14px/1.4 system-ui;cursor:pointer;text-decoration:none}button:hover,nav a:hover{border-color:#d3a0b9}button:focus-visible,a:focus-visible{outline:2px solid #ffdfef;outline-offset:4px}.status{display:inline-block;padding:7px 12px;border:1px solid #8a6171;border-radius:7px;color:#f2c9d7}video{display:block;background:#000;width:100%;max-height:86vh;border:1px solid #4c3e4c;border-radius:8px;margin:24px 0 16px}.mobile-video{max-width:390px}.chapters{gap:8px}.chapters button{font-weight:500;text-align:left;padding:9px 12px;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}figure{margin:0}figure img{display:block;width:100%;border:1px solid #433744;border-radius:6px}figure.phone{max-width:390px}figcaption{padding:9px 0;color:#c7bec8;font-size:14px}.note{border-left:3px solid #a45f79;padding-left:18px}pre{white-space:pre-wrap;color:#d3c9d6;font:14px/1.6 ui-monospace,monospace}footer{margin-top:60px;color:#aa9dab}@media(max-width:700px){.grid{grid-template-columns:1fr}main{padding:24px 16px 50px}video{max-height:80vh}}
</style><main><span class="status">ownerVisualApproval: OPEN</span><h1>Jeden świat. Różne strefy instalacji.</h1><p>Lokalny living pass · 4 listopada 2026. Zachowane treści, katalog, statusy, analytics i obecny Core. Bez commita, pushu i publikacji.</p><nav><a href="/">Otwórz stronę</a><a href="QA.json">Wyniki kontroli</a><a href="ODBIOR.txt">Zakres i pliki</a></nav>
<h2>Desktop — rzeczywiste nagranie przeglądarki</h2><p>Postoje po 5,5 sekundy w Hero, Core, Showroom, Process, Ecosystem i Contact, następnie ruch kursora. Widoczna strzałka pochodzi wyłącznie z nagrania i śledzi prawdziwe zdarzenia wskaźnika.</p><video id="desktop" controls playsinline preload="metadata" poster="desktop-hero.png"><source src="desktop.mp4" type="video/mp4"></video><div class="chapters">DESKTOP_CHAPTERS</div>
<h2>Mobile — krótszy walkthrough</h2><p>Chrome: 390 × 844 px, emulacja dotyku. Nie jest to test na fizycznym telefonie.</p><video class="mobile-video" id="mobile" controls playsinline preload="metadata" poster="mobile-showroom.png"><source src="mobile.mp4" type="video/mp4"></video><div class="chapters">MOBILE_CHAPTERS</div>
<h2>Kadry do odbioru</h2><div class="grid">FIGURES</div><h2>Kontrola lokalna</h2><p class="note">Ocena estetyczna pozostaje otwarta. Płynność filmu i FPS renderera to odrębne pomiary. Szczegóły próbek i ograniczeń znajdują się w raporcie.</p><pre id="checks">Wyniki: QA.json</pre><footer>ProgressKit Systems · local state · ownerVisualApproval: OPEN</footer></main><script>
document.querySelectorAll('[data-video]').forEach(b=>b.addEventListener('click',()=>{const v=document.getElementById(b.dataset.video);document.querySelectorAll('video').forEach(o=>{if(o!==v)o.pause()});v.currentTime=+b.dataset.time;v.play().catch(()=>{});v.scrollIntoView({behavior:'smooth',block:'center'})}));
fetch('QA.json').then(r=>r.json()).then(q=>{document.getElementById('checks').textContent='Browser: '+q.browser.PASS+' PASS / '+q.browser.FAIL+' FAIL\\nJavaScript: '+q.javascriptTests.PASS+' PASS\\nPython: '+q.pythonTests.PASS+' PASS\\n'+q.performance.summary+'\\nownerVisualApproval: OPEN'}).catch(()=>{});
</script></html>'''
(p/'index.html').write_text(html.replace('DESKTOP_CHAPTERS',chapters('desktop')).replace('MOBILE_CHAPTERS',chapters('mobile')).replace('FIGURES',figures))
print('Gallery:',len(screens),'screens')
